def verify_sources(inv):
 working=(HERE.parent/'servers/silk-shell/src/main.rs').read_text();pinned=run(['git','show',inv['pin']+':servers/silk-shell/src/main.rs'],ok=True).decode();assert hashlib.sha256(working.encode()).hexdigest()==inv['working_main_sha256']
